class CodeToken {
 final String kind,text;const CodeToken(this.kind,this.text);
 Map<String,String> toJson()=>{'kind':kind,'text':text};
}
final _keywords='const let var final class return if else true false null void async await import export function new extends throw try catch required this super static'.split(' ').toSet();
List<CodeToken> codeTokens(Object? source){if(source is! String||source.length>32768)throw const FormatException('invalid_code');final code=source,out=<CodeToken>[];void add(String kind,String text){if(out.isNotEmpty&&out.last.kind==kind){out[out.length-1]=CodeToken(kind,out.last.text+text);}else{out.add(CodeToken(kind,text));}}var i=0;final word=RegExp(r'[A-Za-z0-9_$]'),startWord=RegExp(r'[A-Za-z_$]'),number=RegExp(r'[0-9a-fA-F_xX.eE]');while(i<code.length){final start=i,c=code[i];if(code.startsWith('//',i)){final end=code.indexOf('\n',i+2);i=end<0?code.length:end;add('comment',code.substring(start,i));}else if(code.startsWith('/*',i)){final end=code.indexOf('*/',i+2);i=end<0?code.length:end+2;add('comment',code.substring(start,i));}else if(['"',"'",'`'].contains(c)){i++;while(i<code.length){if(code[i]=='\\'){i=(i+2).clamp(0,code.length).toInt();continue;}if(code[i++]==c)break;}add('string',code.substring(start,i));}else if(startWord.hasMatch(c)){while(i<code.length&&word.hasMatch(code[i])){i++;}final text=code.substring(start,i);add(_keywords.contains(text)?'keyword':'plain',text);}else if(RegExp(r'[0-9]').hasMatch(c)){while(i<code.length&&number.hasMatch(code[i])){i++;}add('number',code.substring(start,i));}else{i++;add('plain',c);}}return List.unmodifiable(out);}
int remainingSeconds(Object? deadline,Object? now){if(deadline is! int||now is! int||deadline<0||now<0||deadline>9007199254740991||now>9007199254740991)throw const FormatException('invalid_countdown');final delta=deadline-now;return delta<=0?0:delta~/1000+(delta%1000>0?1:0);}
int responsiveColumns(double width,double minWidth,double gap){if(!width.isFinite||!minWidth.isFinite||!gap.isFinite||width<0||minWidth<=0||gap<0)throw const FormatException('invalid_form_geometry');return ((width+gap)/(minWidth+gap)).floor().clamp(1,12).toInt();}
